(function(){
  var box=document.getElementById('searchBox'),res=document.getElementById('searchRes'),meta=document.getElementById('searchMeta');
  if(box&&res&&window.VOCAB_INDEX){
    function norm(s){return (s||'').toLowerCase().replace(/[()\[\]'.,;:]/g,' ').replace(/\s+/g,' ').trim();}
    box.addEventListener('input',function(){
      var q=norm(box.value);
      if(q.length<1){res.style.display='none';meta.textContent='';return;}
      var parts=q.split(' ');
      var hits=[],max=50;
      for(var i=0;i<window.VOCAB_INDEX.length&&hits.length<max;i++){
        var it=window.VOCAB_INDEX[i],hit=true;
        for(var j=0;j<parts.length;j++){if(parts[j]&&norm(it.w).indexOf(parts[j])<0&&norm(it.d).indexOf(parts[j])<0){hit=false;break;}}
        if(hit)hits.push(it);
      }
      if(hits.length===0){res.style.display='block';res.innerHTML='<div class="item" style="color:#7f8c8d">無符合單字</div>';meta.textContent='共 0 筆';return;}
      meta.textContent='共 '+hits.length+' 筆（最多顯示 50）';
      res.innerHTML=hits.map(function(it){
        var d=it.d||'',ds=d.length>60?(d.slice(0,60)+'…'):d;
        var p=it.p?'<span class="p">'+it.p.replace(/[\[\]]/g,'')+'</span>':'';
        return '<div class="item" data-lv="'+it.lv+'" data-i="'+it.i+'"><span class="w">'+it.w+'</span><span class="lv">'+it.lv+'</span>'+p+'<div class="d">'+ds+'</div></div>';
      }).join('');
      res.style.display='block';
    });
    res.addEventListener('click',function(e){
      var t=e.target.closest('.item');if(!t)return;
      location.href='level'+t.dataset.lv.replace('L','')+'.html#c'+t.dataset.i;
    });
  }
  if('serviceWorker' in navigator){window.addEventListener('load',function(){navigator.serviceWorker.register('sw.js').catch(function(e){console.warn('SW 註冊失敗',e)})});}
})();
